#!/usr/bin/env node
/**
 * build-html.js — 将 broadcast/ 源文件合并为 worker/broadcast-html.js
 *
 * 流程：
 *   1. 读 broadcast/src/*.js 按文件名排序拼接（唯一手写来源）
 *   2. 读 broadcast/index.html + broadcast/styles.css
 *   3. 内联 CSS/JS → 转义模板字面量 → 输出线上产物
 *   4. 同时生成 broadcast/app.js 开发版 bundle
 *
 * 为什么要生成 broadcast/app.js：
 *   index.html 里写的是 <script src="./app.js">，直接用浏览器打开
 *   broadcast/index.html 时加载的就是这个文件。如果它是手写的旧代码，
 *   本地看到的和线上跑的就是两套东西 —— 手工双副本问题原地复活。
 *   所以 app.js 必须也由本脚本生成，且带 AUTO-GENERATED 头。
 *
 * 配套：deploy.sh 在 wrangler deploy 前自动调用此脚本
 */
import { readFileSync, writeFileSync, readdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const BROADCAST_DIR = join(ROOT, "broadcast");
const SRC_DIR = join(BROADCAST_DIR, "src");
const OUTPUT = join(ROOT, "worker", "broadcast-html.js");
const DEV_BUNDLE = join(BROADCAST_DIR, "app.js");

/** 失败就退出，绝不静默产出半成品 */
function fail(msg) {
  console.error(`❌ build-html.js: ${msg}`);
  process.exit(1);
}

// ── 读取源文件 ────────────────────────────────────────────────────────────────
const html = readFileSync(join(BROADCAST_DIR, "index.html"), "utf-8");
const css = readFileSync(join(BROADCAST_DIR, "styles.css"), "utf-8");

// 读取 broadcast/src/*.js 按文件名排序拼接（00- 10- 20- … 的前缀就是加载顺序）
const srcFiles = readdirSync(SRC_DIR)
  .filter((f) => f.endsWith(".js"))
  .sort();

if (srcFiles.length === 0) fail(`${SRC_DIR} 下没有任何 .js 模块`);

const jsModules = srcFiles.map((f) => {
  const content = readFileSync(join(SRC_DIR, f), "utf-8");
  if (!content.trim()) fail(`模块 ${f} 是空文件`);
  return `// ── ${f} ───────────────────────────────────────────────────────────────\n${content}`;
});
const js = jsModules.join("\n\n");

console.log(`📂 读取 ${srcFiles.length} 个模块: ${srcFiles.join(", ")}`);

// ── 内联替换 ──────────────────────────────────────────────────────────────────
// 注意：String.replace 不匹配时会**原样返回**，不报错。
// 如果 index.html 里的标签写法变了而这里的正则没跟上，就会产出一个
// 仍然引用 ./styles.css 和 ./app.js 的页面 —— 而 Worker 不提供这两个路径，
// 结果是白屏。所以每一步都必须断言替换真的发生了。
const CSS_TAG = /<link\s+rel="stylesheet"\s+href="\.\/styles\.css"\s*\/?>/;
const JS_TAG = /<script\s+src="\.\/app\.js"\s*defer\s*><\/script>/;

if (!CSS_TAG.test(html)) fail("index.html 里找不到 styles.css 的 <link> 标签，无法内联 CSS");
if (!JS_TAG.test(html)) fail("index.html 里找不到 app.js 的 <script> 标签，无法内联 JS");

let result = html.replace(CSS_TAG, `<style>\n${css}\n</style>`);
result = result.replace(JS_TAG, `<script defer>\n${js}\n</script>`);

// 兜底自检：内联后不应再残留对外部资源的引用
if (/src="\.\/app\.js"/.test(result) || /href="\.\/styles\.css"/.test(result)) {
  fail("内联后仍残留外部资源引用，产物不可用");
}

// ── 转义模板字面量特殊字符（顺序敏感）────────────────────────────────────────
// 1. 反斜杠必须最先处理（否则后面插入的 \` 会被二次转义）
// 2. 反引号 → \`
// 3. ${ → \${（防止 JS 模板引擎解析）
result = result.replace(/\\/g, "\\\\");
result = result.replace(/`/g, "\\`");
result = result.replace(/\$\{/g, "\\${");

// ── 组装最终输出 ──────────────────────────────────────────────────────────────
const header = `// AUTO-GENERATED by scripts/build-html.js — do not edit manually
// Source: broadcast/src/*.js + broadcast/{index.html, styles.css}
// Modules: ${srcFiles.join(", ")}
// Rebuild: node scripts/build-html.js`;

const output = `${header}
export const broadcastHtml = \`${result}\`;
`;

writeFileSync(OUTPUT, output, "utf-8");
console.log(`✅ 线上产物: ${OUTPUT} (${(output.length / 1024).toFixed(1)} KB)`);

// ── 开发版 bundle：让本地直接打开 index.html 与线上完全一致 ────────────────────
// 这一份不做模板字面量转义（它是被 <script src> 直接加载的普通 JS）
const devBundle = `// AUTO-GENERATED by scripts/build-html.js — do not edit manually
// 本文件是 broadcast/src/*.js 的开发版打包结果，用于本地直接打开 index.html。
// 要改前端行为，请改 broadcast/src/ 下的模块，然后跑 node scripts/build-html.js。
// Modules: ${srcFiles.join(", ")}

${js}
`;

writeFileSync(DEV_BUNDLE, devBundle, "utf-8");
console.log(`✅ 开发 bundle: ${DEV_BUNDLE} (${(devBundle.length / 1024).toFixed(1)} KB)`);
